import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

export const LINE_COLOR = Colors.Text.Neutral.Subdued;
const BORDER = '1px';
const BORDER_LINE = `${BORDER} solid ${LINE_COLOR}`;

interface ChartOverlaysBorderProps {
  left?: boolean;
  right?: boolean;
}

export const ChartOverlaysBorder = /* @__PURE__ */ styled(
  'div',
)<ChartOverlaysBorderProps>(({ left, right }) => ({
  position: 'absolute',
  width: `calc(100% - ${BORDER})`,
  height: '100%',
  pointerEvents: 'none',
  borderLeft: left ? BORDER_LINE : '',
  borderRight: right ? BORDER_LINE : '',
  borderBottom: BORDER_LINE,
  /* Using content-box avoids other overlays to go beyond border */
  boxSizing: 'content-box',
}));
